DROP TABLE IF EXISTS tbl_blogs;

CREATE TABLE tbl_blogs (
    id int(11) NOT NULL AUTO_INCREMENT PRIMARY KEY,
    idAdministrador int(11) NOT NULL,
    idCategoria int(2) NOT NULL,
    titulo varchar(400) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci NOT NULL,
    descripcionPrincipal varchar(10000) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci NOT NULL,
    descripcionSecundaria mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci NOT NULL,
    imagen varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci NOT NULL,
    fechaPublicacion date DEFAULT NULL,
    estadoRevisionTexto int(2) NOT NULL DEFAULT 0,
    estadoRevisionMultimedia int(2) NOT NULL DEFAULT 0,
    autor varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci NOT NULL DEFAULT '',
    textoBoton varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci NOT NULL DEFAULT 'Read more',
    blogMeGusta int(11) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

INSERT INTO `tbl_blogs` (`id`, `idAdministrador`, `idCategoria`, `titulo`, `descripcionPrincipal`, `descripcionSecundaria`, `imagen`, `fechaPublicacion`, `estadoRevisionTexto`, `estadoRevisionMultimedia`, `autor`, `textoBoton`, `blogMeGusta`) VALUES
(1, 18, 3, 'Thoughts in the Unicab Virtual Ecosystem', 'In this space, we share a part of our UNICAB learning ecosystem, which is aligned with Millennium Development Goal (MDG) 4, ensuring inclusive, equitable, and quality education, and promoting lifelong learning opportunities for all. Our UNICAB Virtual College is structured around five core principles designed to integrate knowledge and strengthen critical thinking skills for life, always keeping in mind that the student is our top priority. Therefore, we invite you to explore the following information and discover how these principles are organized across various areas and fields of knowledge.', '<iframe width=\"600\" height=\"340\" src=\"https://view.genial.ly/65c79e49b8f4130014ce634e\" \ntitle=\"THOUGHTS AT UNICAB\" frameborder=\"0\" type=\"text/html\"\nallowscriptaccess=\"always\" allowfullscreen=\"true\" scrolling=\"yes\"\nallownetworking=\"all\"></iframe><p>SWe continue</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/pie_conectados.jpg\" width=\"600\" class=\"img-fluid\"/></p>', 'https://unicab.org/assets/img/imgblog/PENSAMIENTO_1.jpg', '2024-02-23', 18, 18, 'By: Unicab Research Group, GIU', 'Read more', 0),
(2, 18, 3, 'The urgency to accelerate investments and results in education.', '<p style=\"text-align: justify;\">(Inter-American Development Bank) IDB – conference held virtually via LinkedIn. March 6-10, 2024.</p>\n<p style=\"text-align: justify;\">The Programme for International Student Assessment (PISA) of the Organisation for Economic Co-operation and Development (OECD) is the leading international test that measures and compares the knowledge and skills of 15-year-old students. Fourteen Latin American and Caribbean countries participated in the latest test, the results of which were released in December 2023. The Inter-American Development Bank (IDB) published a series of summaries highlighting the region´s main results and, together with the World Bank, is preparing a report to analyze them in depth, as part of the activities outlined in the Memorandum of Understanding signed by both institutions on August 31, 2023. The report was launched at this event, and the information from the summaries was also presented. The session began with a 10-minute technical presentation on the region´s PISA test results, followed by a discussion on (i) the learning crisis in the region, (ii) innovative solutions to the current learning crisis, (iii) policies to transform education systems and make them more resilient to learning losses, (iv) the role of digitization in recovery from learning crises and the transformation of education systems, and (v) innovative financing strategies for smart spending on education.</p>\n', '<p>The global challenge is learning:</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/2_1.png\" width=\"600\" class=\"img-fluid\"/></p><br><p >In-depth analysis of the results shows that: in Mathematics, 3 out of 4 students have low performance; this occurs in 75% of students in Latin America compared to 35% of students in other OECD countries; in Reading, 1 out of 2 students have low performance; this occurs in 55% of students in Latin America compared to 26% of students in other OECD countries.</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/3_1.png\" width=\"600\" class=\"img-fluid\"/></p><br><p class=\"ql-align-justify\">If learning were a disease, we would be talking about a global pandemic; this is the reason why this report was published today (Wednesday, March 6, 2024).</p><br><p class=\"ql-align-justify\">LEARNING CAN´T WAIT: <strong><em>LEARNING CAN´T WAIT</em></strong>To better understand the reasons behind this learning crisis in Latin America, we present what we know:</p><br><p>THE WHERE</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/4_1.png\" width=\"600\" class=\"img-fluid\"/></p><br><p>On average, 15-year-old students in the region are 5 years behind the average student in OECD countries; compared to countries above, the delay is 10 years compared to Singapore.</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/5_1.png\" width=\"600\" class=\"img-fluid\"/></p><br><p>We also know within countries WHO these lagging students are, where they are located; The graph shows the percentage of low-performing students in mathematics, the blue dots are low-income students, the darker dots are high-income students; 88% of low-income students are low-performing, compared to 55% of their high-income peers.</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/6_1.png\" width=\"600\" class=\"img-fluid\"/></p><br><p class=\"ql-align-justify\">We not only know where, but we know WHY:</p><br><p>1. We are not investing enough in education; the countries in red are at the bottom of the investment distribution.</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/7_1.png\" width=\"600\" class=\"img-fluid\"/></p><br><p class=\"ql-align-justify\">2. There is a direct relationship between investment and learning.</p><br><p>3. By adding the trend line, we see that the countries in the region are below the trend line; there is an efficiency problem, meaning that the countries could be achieving more for every dollar they invest.</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/8_1.png\" width=\"600\" class=\"img-fluid\"/></p><br><p class=\"ql-align-justify\">There is an investment problem in terms of amount, there is an efficiency problem, there is a distribution problem and therefore an equity problem.</p><br><p>The main input that the education system has in its production function to cause learning is the teacher; this input is unequally distributed, the highest quality teachers are where the highest income students are.</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/9_1.png\" width=\"600\" class=\"img-fluid\"/></p><br><p class=\"ql-align-justify\">WE KNOW WHAT THE SOLUTIONS ARE:</p><br><p>1. It is essential to measure more and better; we must regularly measure learning. This means that today we know where we are with a sense of purpose and direction, which indicates where we want to go in the coming years.</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/10_1.png\" width=\"600\" class=\"img-fluid\"/></p><br><p>2. We need to invest more.</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/11_1.png\" width=\"600\" class=\"img-fluid\"/></p><br><p>3. But we also need to invest better, generate efficiencies, spend better, invest in programs that we know are effective, in programs that make a difference in terms of learning.</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/12_1.png\" width=\"600\" class=\"img-fluid\"/></p><br><p>We know that offering young children good literacy programs can improve their reading skills by 30%. For example: The "Let´s All Learn to Read" program.</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/13_1.png\" width=\"600\" class=\"img-fluid\"/></p><br><p>We also know that when we culturally contextualize the mathematics program, for example:</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/14_1.png\" width=\"600\" class=\"img-fluid\"/></p><br><p class=\"ql-align-justify\">We helped indigenous children develop 50% more of those mathematical skills.</p><br><p>We also know:</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/15_1.png\" width=\"600\" class=\"img-fluid\"/></p><br><p>When we provide personalized support to the most vulnerable and struggling students through remote tutoring, which is highly effective and inexpensive, we manage to accelerate their learning by 30%.</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/16_1.png\" width=\"600\" class=\"img-fluid\"/></p><br><p>We also know that when we offer school meals to students, we achieve greater participation in school and increased school attendance, with a 9% improvement. Finally:</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/17_1.png\" width=\"600\" class=\"img-fluid\"/></p><br><p class=\"ql-align-justify\">It is essential to have management and information systems: to generate efficiencies, equity, to better and more equitably distribute the resources of the education system, to compensate for those differences at birth.</p><br><p>The challenge is to achieve those benefits already obtained at scale.</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/18_1.png\" width=\"600\" class=\"img-fluid\"/></p><br><p class=\"ql-align-justify\">The IDB 2024 initiative focuses on modernizing education and ensuring its financing. It proposes a flexible, personalized, and technology-driven education, with an emphasis on reducing inequalities and improving educational quality. A financing fund is envisioned, with collaboration between governments, international organizations, and the private sector, to drive these changes and build a more equitable and promising educational future. To meet the challenges we face, it is crucial to implement concrete and coordinated actions. How can we ensure that the education of the future is flexible, personalized, and technology-driven, while simultaneously reducing inequalities and improving its quality?</p><br><p>Thank you for reading this report. And we continue...</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/pie_conectados.jpg\" width=\"600\" class=\"img-fluid\"/></p>', 'https://unicab.org/assets/img/imgblog/1_1.png', '2024-03-27', 18, 18, 'By Diane Billón Villarreal and Stella Hurtado Rodríguez', 'Read more', 0),
(3, 18, 2, 'Education that shapes the mind and soul', 'Currently we know that education, more than a right, is seen as a privilege due to the difficulty some people have in accessing it; this is why inclusive education arises, which seeks access to quality learning for all. However, this training loses its purpose when it only fills with intellectual knowledge, which is why an inclusive and comprehensive education is necessary.', '<p><iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/uclA1l6EE-4?si=1QlNsi9qtPHda_0X\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe></p><br><p><strong>Bibliography:</strong></p><br><p>López, P. (2022, March 22). +50 Quotes from DON BOSCO - On education and prayer! . Quotes. <a href=\"https://www.frasess.net/frases-de-don-bosco-898.html\">href=\"https://www.frasess.net/frases-de-don-bosco-898.html</a></p><br><p>Inclusive education: A more participatory vision for boys and girls. (2021, July 23). Colombia Aprende. <a href=\"http://www.colombiaaprende.edu.co/agenda/tips-y-orientaciones/educacion-inclusiva-una-vision-mas-participativa-para-ninos-y-ninas\">href=\"http://www.colombiaaprende.edu.co/agenda/tips-y-orientaciones/educacion-inclusiva-una-vision-mas-participativa-para-ninos-y-ninas</a></p><br><p>Political Constitution of Colombia. Article 67.1991</p><br><p>Huelga, L. A. (2018, March 22). Moral intellectualism, or how to walk the path of good. Philosophy & Co. <a href=\"https://filco.es/intelectualismo-moral-camino-del-bien/\">https://filco.es/intelectualismo-moral-camino-del-bien</a></p>', 'https://unicab.org/assets/img/imgblog/educacion_1.jpg', '2024-05-06', 18, 18, 'By the student, Luna María Gómez López ', 'Read more', 0),
(4, 18, 3, 'THE REVOLUTION OF NATURAL INTELLIGENCE', 'Dear readers:<br>\nIn the midst of a constantly shifting and evolving technological landscape, 2024 presents itself as a significant year and a milestone in this field. The speed and scope of technological change pose a challenge at every level and in every area of ​​knowledge. \nArtificial Intelligence is the hottest topic in various media and settings. The very word "artificial" makes many of us uneasy, even though work on machines that mimic human intelligence has been ongoing for a long time, along with myths and legends about automatons and thinking machines.', '<p>An article by Arrestegui in 2012 points out that the interest in reproducing human characteristics through man-made devices has a long history, beginning with the very existence of humankind. The need to transfer labor to machines that perform it automatically, without errors, and that maximize energy use has been met throughout history with the development of machines ranging from the simple plow to the complex computer. (Arrestegui, 2012).</p><br><p style=\"text-align: center;\"><img src=\"https://unicab.org/assets/img/imgblog/2intnat_1.png\" width=\"600\" class=\"img-fluid\"/><em style=\"color: rgb(127, 127, 127); font-size: 12px;\">Illustration made by artist Yanni Sophia Noriega, former student of Unicab</em></p><br><p class=\"ql-align-justify\">It was not until the middle of the 20th century that its true potential was investigated, after the first electronic computers were developed.</p><br><p class=\"ql-align-justify\">Within the fields of systems and computer science, Artificial Intelligence is probably the most spectacular area of ​​research, the one that has attracted the most interest from both novices and scientists, with the goal of making computers think. Furthermore, disciplines such as mathematics and all the basic sciences, psychology, linguistics, philosophy, and, of course, computer science actively participate, as they have shaped, through their contributions, the characteristics of representing and processing information and knowledge. (UNAM, 2018).</p><br><p class=\"ql-align-justify\"><strong><em>Why does Artificial Intelligence generate so much controversy? Will it improve our lives or worsen them?</em></strong></p><br><p class=\"ql-align-justify\">The UN General Assembly believes that the proper development of this technology fosters digital transformation, promotes peace, bridges the digital divide both within and between countries, and even promotes the protection and enjoyment of human rights. We are left wondering, is all of this true, and how would these benefits be achieved?</p><br><p class=\"ql-align-justify\">On March 22 of this year, the UN adopted its first resolution on Artificial Intelligence, aiming to promote its safe, responsible, and equitable development to prevent inequalities between countries and its potential for malicious use. Given the importance of the issue, the UN urges member states of the General Assembly to review and legislate on the matter.</p><br><p class=\"ql-align-justify\">The debate began in Colombia in 2019 regarding regulatory discussions, governance, and implementation of Artificial Intelligence, and as of 2022, we have two projects underway in the country: <strong>the AI ​​public policy lab and the AprendeIA empowerment platform </strong>and a document on AI and sustainability was prepared. (GovTech and Public Impact Lab, 2022).</p><br><p class=\"ql-align-justify\">The Bogotá Chamber of Commerce implemented the AI ​​lab initiative to focus on generating value for Colombian society and the economy. (Bogotá Chamber of Commerce, 2021). </p><br><p class=\"ql-align-justify\">To date, there are certainly many other initiatives to review and analyze the importance, scope, and effects of AI, which, as we all know, is a field still under development and will continue to change daily. At the Unicab Research Group (GIU), we observe that despite all that Artificial Intelligence has achieved, thanks to the<strong>revolution for natural intelligence</strong> which is the main architect of this achievement. We admit that AI still has much to learn and has had a positive impact in areas such as health, finance, education, agriculture, energy, logistics and transportation, and at a commercial level, but it also poses risks, such as for decision-making, since the concepts of Artificial Intelligence can be biased and unfair.</p><br><p class=\"ql-align-justify\">Our readers will agree that other risks may be evident, for example, in the possible violation of privacy, job displacement, being used for malicious purposes such as the development of more sophisticated cyberattacks, raising ethical issues in critical situations such as in the health sector or the justice and security sector, and the concern that Artificial Intelligence may surpass natural, human intelligence to the point of controlling us.</p><br><p class=\"ql-align-justify\">In education, Artificial Intelligence raises a major ethical debate and is a subject of analysis due to its increasing implementation. We are very motivated by its use at Unicab and invite the entire educational community to ensure that its use is rational and<em>Don´t believe the hype.</em> and that, therefore, there is a work of natural intelligence in contrasting with other sources of information the veracity of what AI tells us.</p><br><p>We also want to continue motivating ourselves to argue and support in our own words what we obtain from our research and consultations, to maintain and strengthen our natural cognitive, emotional and volitional faculties that give human beings the capacity for an inner look at our own actions, to value, evaluate, interpret, interact, feel, be moved and respond to the environment… Even to feel fascination and sometimes frustration with the decisions we make.</p><br><p>We continue...</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/pie_conectados.jpg\" width=\"600\" class=\"img-fluid\"/></p><br><p><strong>References:</strong></p><br><p>Arrestegui, L. B. (2012). Theoretical and philosophical foundations of Artificial Intelligence. <em>Journal of Research and Culture</em>, 87-92.</p><br><p>Bogotá Chamber of Commerce. (December 13, 2021). <em>Bogotá Chamber of Commerce</em>. Obtained from <a href=\"https://www.ccb.org.co/empresarial/apoyo-sostenibilidad-empresarial/innovaciones-y-soluciones-tecnologicas/sobre-policy-lab\">https://www.ccb.org.co/empresarial/apoyo-sostenibilidad-empresarial/innovaciones-y-soluciones-tecnologicas/sobre-policy-lab</a></p><br><p>GovTech and Public Impact Lab. (July 25, 2022). <em>Milab</em>. Obtained from <a href=\"https://www.innpulsacolombia.com/milab/noticias/politica-de-inteligencia-artificial-ia-para-colombia\">https://www.innpulsacolombia.com/milab/noticias/politica-de-inteligencia-artificial-ia-para-colombia</a></p><br><p>UNAM, G. d. (2018). <em>Intelligent Systems Research Group of the Autonomous University of Mexico</em>. Obtained from <a href=\"https://virtual.cuautitlan.unam.mx/intar/sistdig/algebra-booleana/\">https://virtual.cuautitlan.unam.mx/intar/sistdig/algebra-booleana/</a></p>', 'https://unicab.org/assets/img/imgblog/1intnat_1.png', '2024-05-21', 18, 18, 'By: Unicab Research Group, GIU', 'Read more', 0),
(5, 18, 3, 'DIGITAL COMPETENCIES FROM THE UNICAB VIRTUAL SCHOOL', 'Major technological advances in various fields have led us to adopt digital skills in our daily lives, facilitating many tasks such as scheduling medical appointments, shopping online, using social media, and downloading and installing apps on our phones. This has allowed us to be more creative, competitive, and improve products and services. But, speaking specifically about the educational sphere, how do these digital skills manifest themselves in education? And what should we, as teachers and facilitators of knowledge, keep in mind?', '<p class=\"ql-align-justify\">Below, we share our vision and perspective from our UNICAB Virtual school, with our model called the UNICAB Virtual Ecosystem for e-learning for primary and secondary education. We have defined digital competencies from the perspective of the European Framework for Digital Competence of Educators (DigCompEdu) and the ICT Competence standards for teachers proposed by UNESCO.</p><br><p><iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/GGoB36E5oc4?si=q5b4O3KJl7u9MJMZ\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe></p><br><p><strong><em>References. </em></strong></p><br><p>Suárez, J., Cadena, S., Monroy, J., &amp; Hurtado, S. (2020). Theoretical foundation of the Unicab Virtual Ecosystem. Unicab Virtual School Educational Corporation.</p><br><p>UNESCO. (2022). Roadmap of the Regional Coordination Mechanism (2022-2025) for the advancement of Sustainable Development Goal 4 (SDG4).<br> <a href=\"https://unesdoc.unesco.org/ark:/48223/pf0000385157_spa?posInSet=1&amp;queryId=6c95b8f4-ff66-4cde-9e60-c8296b9f69c2\">https://unesdoc.unesco.org/ark:/48223/pf0000385157_spa?posInSet=1&amp;queryId=6c95b8f4-ff66-4cde-9e60-c8296b9f69c2</a></p><br><p>UNESCO. (2019). ICT Competency Framework for Teachers.</p><br><p>UNESCO. (2023). Global Education Monitoring Report 2023: Technology in education: A tool on whose terms? Paris, France.</p><br><p>Redecker, C. (2020). European framework for the digital competence of educators: DigCompEdu. Publications Office of the European Union.</p>', 'https://unicab.org/assets/img/imgblog/competencias_1.jpg', '2024-06-09', 18, 18, 'By: Unicab Research Group, GIU', 'Read more', 0),
(6, 18, 3, 'WHAT DOES THE GIU DO?', 'Dear readers,\n\nIn 2018, a group of professionals of the highest human and pedagogical qualities, led by the Rector´s Office and the Academic Coordination, put at the service of the community a Pedagogical Model, the product of an intense work of research and development.', '<p class=\"ql-align-justify\">Subsequently, and with the aim of giving&nbsp; support for the institution´s academic activity in relevant and efficiently coordinated research work, which could be presented to educational oversight entities, as well as for participation in academic events at the regional, national and international level and as a basis for the research work that tutors could carry out, through Act 001 of April 30, 2019, the Rectorate of the UNICAB Virtual College&nbsp;formalizes the creation of the UNICAB Research Group, hereinafter GIU.</p><br><p class=\"ql-align-justify\">The first action to be carried out by the GIU, of an urgent nature, given the pressing need to defend the Pedagogical Model before the Sogamoso Education Secretariat, was the <strong>consolidation of the historical process, methodological development and theoretical structure of the virtual education offered by UNICAB, as a benchmark for Basic and Secondary Education in Colombia.</strong></p><br><p class=\"ql-align-justify\">Here, it´s worth clarifying: In Colombia, online schooling is legal but unregulated, which meant that UNICAB had a firm commitment to demonstrate tangibly, with facts and documentation, that this educational alternative was viable and beneficial. At that time, and still today, UNICAB was the only institution offering this purely online pedagogy (hybrid programs exist, but only UNICAB is truly online). </p><br><p class=\"ql-align-justify\">Taking on this responsibility involved determined and constant work and, consequently, the research group was formally started, establishing its mission and defining the first specific objectives.</p><br><p class=\"ql-align-justify\"><strong>GIU Mission</strong> </p><br><p class=\"ql-align-justify\">The GIU´s mission is to be a driving force behind research in virtual education for basic and secondary education in Colombia, creating, absorbing, integrating, and reconfiguring knowledge. The GIU´s ultimate goal is to strengthen research processes, establish interactions and networks with the academic and productive sectors for the implementation of projects that contribute to the development of the region and the country. Likewise, it aims to stimulate the transfer, assimilation, adaptation, and dissemination of knowledge and virtual pedagogical innovation generated at UNICAB to contribute to regional and national development, address the educational needs of families, and promote a culture of progress and sustainability through virtual learning.</p><br><p class=\"ql-align-justify\"><strong>GIU Objectives</strong></p><br><p class=\"ql-align-justify\">1.&nbsp;&nbsp;&nbsp;&nbsp;Develop research, from a multidisciplinary approach given by the Thoughts established in the Institutional Educational Project, PEI, to strengthen the human development of the educational community that UNICAB serves.</p><br><p class=\"ql-align-justify\">2.&nbsp;&nbsp;&nbsp;&nbsp;To contribute to the development of research skills, talents and abilities of tutors and students from a collaborative and participatory approach.</p><br><p class=\"ql-align-justify\">3.&nbsp;&nbsp;&nbsp;&nbsp;Promote the use of knowledge about virtual education to improve the quality of life of the UNICAB educational community.</p><br><p class=\"ql-align-justify\">4.&nbsp;&nbsp;&nbsp;&nbsp;To offer and provide advisory services in research and intervention to public and private institutions and entities in programs and projects related to virtual education for Basic and Secondary education in Colombia.</p><br><p class=\"ql-align-justify\">5.&nbsp;&nbsp;&nbsp;&nbsp;To offer opportunities to develop interdisciplinary research with other groups at the regional, national and international levels, using participatory methodologies. </p><br><p class=\"ql-align-justify\">6.&nbsp;&nbsp;&nbsp;&nbsp;Other specific objectives that may arise in the development of the GIU´s research activity.</p><a href=\"https://unicab.org/assets/descargas/QUE_HACE_EL_GIU.pdf\" target=\"_blank\" style=\"color: #04BFBF;\"><strong> Download full document </strong><img src=\"https://unicab.org/assets/img/pdf.jpg\" class=\"img-fluid\" alt=\"\" width=\"15%\"></a><p>We continue...</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/pie_conectados.jpg\" width=\"600\" class=\"img-fluid\"/></p><br><p><img src=\"https://unicab.org/assets/img/imgblog/pie de pagina.png\" width=\"400\" class=\"img-fluid\"/></p>', 'https://unicab.org/assets/img/imgblog/soporte tecologico.png', '2024-09-05', 18, 18, '<img src=\"https://unicab.org/assets/img/imgblog/Encabezado.png\" width=\"300\" class=\"img-fluid\"/>', 'Read more', 0),
(7, 10, 1, 'GHIBLI-STYLE IMAGES: THE AI-POWERED STYLE THAT WENT VIRAL, BUT DO YOU KNOW ITS BACKGROUND?', 'Author: María Paula Vélez Villegas <br>Unicab Grade 11 <br>Support teacher: Laura Yeraldin Flórez Díaz <br><br>ChatGPT, the AI ​​chatbot developed by OpenAI, can analyze graphs, solve math problems, process photos, answer questions, and, in its most recent and controversial update, generate images with a wide variety of styles. However, this leads us to question whether its use is truly beneficial or, conversely, whether it raises ethical dilemmas that could alter our perception of the world and impact environmental and social sustainability.\r\n', '<p class=\"ql-align-justify\">Following the most recent update to this AI, images converted to the style quickly went viral on social media. <em>Ghibli</em>; However, most people are still unaware of the risks and problems involved in creating a simple image. According to Sergio Parra (2024), a journalist specializing in nature, technology, science, and health for National Geographic, generating a 100-word text in GPT chat consumes around 519 milliliters of water, equivalent to a bottle—a cost that´s hard to believe considering the scarcity of this precious liquid in countries like Ethiopia, in Africa, and even in Colombia, which, although not experiencing greater water stress than others, is currently facing severe water rationing. Furthermore, generating these popular images in this particular style consumes approximately 1 to 2&nbsp;liters, you might wonder&nbsp;<em>what&nbsp;Does water have anything to do with using AI?,</em> and he explains it in the following way&nbsp;he&nbsp;Professor in the College of Electrical and Computer Engineering at the University of California, Riverside. </p><br><p><img src=\"https://unicab.org/assets/img/imgblog/Imagen1bbb.jpg\" width=\"600\" class=\"img-fluid\"/><br><small><strong>Source: X</strong></small></p><br><p class=\"ql-align-justify\">Shaolei Ren explains that AI models, such as OpenAI´s GPT, are typically trained on server clusters with multiple graphics processing units (GPUs), which consume a significant amount of power. To prevent these devices from overheating, external air systems and cooling towers are used, which require large quantities of water. </p><br><p class=\"ql-align-justify\"><em>Have you ever wondered how the creation of these images affects the environment?</em></p><br><p><img src=\"https://unicab.org/assets/img/imgblog/gggggg.jpg\" width=\"600\" class=\"img-fluid\"/><br><small><strong>Source: Prensa Libre</strong></small></p><br><p class=\"ql-align-justify\">On the other hand, there´s the ethical aspect. Hayao Miyazaki, co-founder of Studio Ghibli, once reacted to an AI-generated animation in 2016 and referred to it as <em>disgusting and an insult to life itself.</em> He has a five-decade career, characterized by using&nbsp;Traditional animation techniques, with meticulous attention to detail, such as shadows, scale, and textures, are what the audience perceives. According to the unanimous opinion of critics worldwide, he is one of the greatest animators in history. But now, with a click, you can hold in your hands photos of yourself and your family, as if they were taken by the same artist. </p><br><p class=\"ql-align-justify\">The ethical dilemma lies in recognizing copyright and respecting original creative work. To give an example, it´s as if you spent your entire life working on research, and when it´s published, the Academy takes it and adds it to its vast databases, which contain all kinds of content: books, articles, websites, and more, without you receiving proper acknowledgment or citations. As the partner at Studio Ghibli puts it: <em>In an age where technology attempts to replicate humanity, we are thrilled that audiences appreciate a cinematic experience that respects and celebrates Hayao Miyazaki and Studio Ghibli´s masterpiece in all its hand-drawn cinematic splendor.</em></p><br><p class=\"ql-align-justify\"><img src=\"https://unicab.org/assets/img/imgblog/gerot.jpg\" width=\"600\" class=\"img-fluid\"/><br><small><strong>Source: Hobby Consolas</strong></small></p><br><p class=\"ql-align-justify\">&nbsp;And this is precisely why you should always cite your research sources and not leave everything to Artificial Intelligence. This is a tool that´s here to stay and will continue to evolve; however, it´s your responsibility to use it wisely. I believe that machines will never be superior to human beings unless we allow it, because we have something they lack: consciousness, will, and reasoning. If you leave your work to AI, you will eventually lose all these abilities. Furthermore, we must remember that these were bestowed upon us by a Supreme Being, not by the creator of technology. </p><br><p class=\"ql-align-justify\"><em>Do you think it´s right for someone to replicate another person´s work without giving them the proper copyright?</em></p><br><p class=\"ql-align-justify\">Last but not least, providing your photographs could pose a threat to your personal data. As Camila Méndez (2025) states, by having access to faces, cybercriminals could play bad tricks, since, being a free tool, it is more likely that each of the data and attached files will remain somewhere on the internet or in different artificial intelligences. </p><br><p><img src=\"https://unicab.org/assets/img/imgblog/meror.jpg\" width=\"600\" class=\"img-fluid\"/><br><small><strong>Source: El Tiempo</strong></small></p><br><p class=\"ql-align-justify\">Uploading your photos to these sites carries the risk of your facial biometrics being collected, making you more vulnerable to theft or hacking of accounts, from social media to bank accounts. Because you´ve never been a public figure, uploading a photo of Messi, who is a public figure, is different from uploading a family photo that has never been on public social media.&nbsp;</p><br><p class=\"ql-align-justify\">Mónica Vargas (2025), Master in Artificial Intelligence, states: When the user uses these tools for free, the product is the user; that is, their data is sold for, for example, advertising of other products.&nbsp;And so, with the large number of faces burdened to&nbsp;Artificial intelligence allows some cybercriminals to create ´master fingerprints´, which combine certain common characteristics of several people around the world, in order to break security methods.</p><br><p class=\"ql-align-justify\"><img src=\"https://unicab.org/assets/img/imgblog/bbbbbbbbb.png\" width=\"600\" class=\"img-fluid\"/><br><small><strong>Source: La Nación</strong></small></p><br><p>We continue...</p><br><p><img src=\"https://unicab.org/assets/img/imgblog/pie_conectados.jpg\" width=\"600\" class=\"img-fluid\"/></p>', 'https://unicab.org/assets/img/imgblog/cahhh.jpg', '2025-04-09', 18, 18, 'María Paula Vélez Villegas', 'Read more', 0);
